// Content-Security-Policy: moderate, integration-aware. Uses 'unsafe-inline'
// (no nonce infra yet) but still adds real protections — object-src none,
// base-uri/form-action self, frame-ancestors none, and script/frame allowlists
// for Stripe + analytics. connect-src is permissive to keep the console (wss)
// and API integrations working.
const csp = [
  "default-src 'self'",
  "base-uri 'self'",
  "object-src 'none'",
  "frame-ancestors 'none'",
  "form-action 'self'",
  "img-src 'self' data: blob: https:",
  "font-src 'self' data:",
  "style-src 'self' 'unsafe-inline'",
  // PayPal's JS SDK (loaded by @paypal/react-paypal-js on the embedded Payment
  // step) both executes a script from paypal.com/paypalobjects.com AND opens an
  // in-page iframe from the same origins for the button + approval flow — found
  // by actually loading the page in a real browser (Playwright) during the
  // embedded-payment-UI build, where the button silently failed to render with
  // nothing but a CSP violation in the console. Sandbox's domain is included too
  // so a `PAYPAL_MODE=sandbox` testing session isn't the ONE environment this
  // never got exercised in.
  "script-src 'self' 'unsafe-inline' 'unsafe-eval' https://plausible.io https://*.googletagmanager.com https://www.google-analytics.com https://js.stripe.com https://www.paypal.com https://www.paypalobjects.com https://www.sandbox.paypal.com",
  "connect-src 'self' https: wss:",
  // blob: lets the webmail render an email body in a sandboxed blob:-URL iframe
  // (a `srcdoc` frame loads as about:srcdoc, which this frame-src refuses). The
  // frame stays fully sandboxed and inherits the rest of this CSP.
  "frame-src 'self' blob: https://js.stripe.com https://hooks.stripe.com https://www.paypal.com https://www.sandbox.paypal.com",
  "worker-src 'self' blob:",
  "manifest-src 'self'",
  "upgrade-insecure-requests",
].join("; ");

const securityHeaders = [
  { key: "Content-Security-Policy", value: csp },
  { key: "X-Content-Type-Options", value: "nosniff" },
  // NOTE: X-Frame-Options is intentionally NOT set here — nginx already sends it,
  // and two conflicting values (DENY vs SAMEORIGIN) is undefined behaviour.
